  const loadAgroRecModuleData = async () => {
    try {
      const res = await fetch('/api/agro-recommendation-module').then((r) => r.json());
      if (res && res.ok) {
        setAgroRecModuleData(res);
        if (res.policy) {
          setRecPolicyForm(res.policy);
        }
      }
    } catch (e) {
      console.error(e);
    }
  };

  const loadRecDongListAndSoil = async (sido: string, sigungu: string, preferredDong?: string, month = recTargetMonth) => {
    try {
      const dRes = await fetch(
        `/api/climate/dongs?sido=${encodeURIComponent(sido)}&sigungu=${encodeURIComponent(sigungu)}`
      ).then((r) => r.json());
      const items = dRes.items || [];
      setRecDongList(items);
      const chosen =
        (preferredDong && items.find((d: any) => d.eupmyeondong === preferredDong)) || items[0] || null;
      if (chosen) {
        setRecDong(chosen.eupmyeondong);
        setRecBjdCode(chosen.bjd_code);
        const ctxRes = await fetch(
          `/api/agro-recommendation-module/region-context?bjd_code=${encodeURIComponent(chosen.bjd_code)}&month=${month}`
        ).then((r) => r.json());
        if (ctxRes && ctxRes.soilSurvey) {
          const s = ctxRes.soilSurvey;
          setRecSoilInput({
            soil_ph: Number(s.soil_ph ?? 6.1),
            soil_ec: Number(s.soil_ec ?? 0.95),
            organic_matter_g_kg: Number(s.organic_matter_g_kg ?? 25),
            avail_p2o5_mg_kg: Number(s.avail_p2o5_mg_kg ?? 440),
            exch_k_cmol: Number(s.exch_k_cmol ?? 0.72),
            exch_ca_cmol: Number(s.exch_ca_cmol ?? 5.8),
            exch_mg_cmol: Number(s.exch_mg_cmol ?? 1.8),
            avail_sio2_mg_kg: Number(s.avail_sio2_mg_kg ?? 185),
            soil_texture: String(s.soil_texture || '양토'),
            land_category: String(s.land_category || '전(밭)'),
          });
        }
      }
    } catch (e) {
      console.error(e);
    }
  };

  const executeAgroRecommendation = async (saveHistory = true, customParams?: Partial<any>) => {
    setIsRecLoading(true);
    try {
      const payload = {
        sido: customParams?.sido ?? recSido,
        sigungu: customParams?.sigungu ?? recSigungu,
        eupmyeondong: customParams?.eupmyeondong ?? recDong,
        bjd_code: customParams?.bjd_code ?? recBjdCode,
        group_id: customParams?.group_id ?? recGroupId,
        crop_id: customParams?.crop_id ?? recCropId,
        cultivar_id: customParams?.cultivar_id ?? recCultivarId,
        process_code: customParams?.process_code ?? recProcessCode,
        target_month: customParams?.target_month ?? recTargetMonth,
        area_pyeong: customParams?.area_pyeong ?? recAreaPyeong,
        ...(customParams?.soilInput ?? recSoilInput),
        save_history: saveHistory,
        source_context: 'ADMIN_SIMULATOR',
      };
      const res = await fetch('/api/agro-recommendation-module/recommend', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      }).then((r) => r.json());
      if (res && res.ok) {
        setRecResult(res);
        if (saveHistory) {
          loadAgroRecModuleData();
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsRecLoading(false);
    }
  };

