  const executeAddressSearch = async (targetPage = 1) => {
    setIsAddrLoading(true);
    try {
      const params = new URLSearchParams({
        sido: addrSidoFilter,
        sigungu: addrSigunguFilter,
        q: addrKeyword.trim(),
        page: String(targetPage),
        pageSize: String(ADDRESS_PAGE_SIZE),
      });
      const res = await fetch(`/api/jibun-addresses?${params.toString()}`).then((r) => r.json());
      setAddressResult({
        items: res.items || [],
        total: res.total || 0,
        page: res.page || 1,
        pageSize: res.pageSize || ADDRESS_PAGE_SIZE,
        totalPages: res.totalPages || 1,
      });
      setHasSearchedAddress(true);
    } catch (e) {
      console.error(e);
    } finally {
      setIsAddrLoading(false);
    }
  };

  const handleSaveAddress = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!addressForm.bjd_code || !addressForm.sido || !addressForm.sigungu || !addressForm.eupmyeondong) return;
    await fetch('/api/jibun-addresses/save', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(addressForm),
    });
    showToast(`지번 주소 [${addressForm.sido} ${addressForm.sigungu} ${addressForm.eupmyeondong}] 저장 완료`);
    setIsAddressModalOpen(false);
    loadAllData();
    if (hasSearchedAddress) {
      executeAddressSearch(addressResult.page);
    }
  };

  const handleDeleteAddress = async (bjdCode: string, fullAddr: string) => {
    if (!window.confirm(`지번 주소 [${fullAddr} (${bjdCode})] 항목을 삭제하시겠습니까?`)) return;
    await fetch('/api/jibun-addresses/delete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ bjd_code: bjdCode }),
    });
    showToast(`지번 주소 [${fullAddr}] 삭제 완료`);
    loadAllData();
    if (hasSearchedAddress) {
      executeAddressSearch(addressResult.page);
    }
  };

