    if (!window.confirm(`도로명 주소 [${fullAddr} (${roadCode})] 항목을 삭제하시겠습니까?`)) return;
    await fetch('/api/road-addresses/delete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ road_code: roadCode }),
    });
    showToast(`도로명 주소 [${fullAddr}] 삭제 완료`);
