  const handleStartKmaModalDrag = (e: React.MouseEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).closest('button, input, select, textarea, a')) return;
    e.preventDefault();
    setIsDraggingKmaModal(true);
    const startX = e.clientX;
    const startY = e.clientY;
    const origX = kmaModalPos.x;
    const origY = kmaModalPos.y;

    const onMouseMove = (moveEvent: MouseEvent) => {
      setKmaModalPos({
        x: origX + (moveEvent.clientX - startX),
        y: origY + (moveEvent.clientY - startY),
      });
    };
    const onMouseUp = () => {
      setIsDraggingKmaModal(false);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };
    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
  };
