  const loadReqDongs = async (sido: string, sigungu: string) => {
    if (!sido || sido === 'ALL' || !sigungu || sigungu === 'ALL') {
      setReqDongList([]);
      return;
    }
    try {
      const params = new URLSearchParams({ sido, sigungu });
      const res = await fetch(`/api/climate/dongs?${params.toString()}`).then((r) => r.json());
      setReqDongList(Array.isArray(res.dongs) ? res.dongs : []);
    } catch {
      // ignore
    }
  };

  const executeScheduleReqSearch = async (override?: {
    group_id?: string;
    crop_id?: string;
    sido?: string;
    sigungu?: string;
    eupmyeondong?: string;
    cultivation_type?: string;
    request_status?: string;
    q?: string;
  }) => {
    setIsReqLoading(true);
    try {
      const params = new URLSearchParams({
        group_id: override?.group_id ?? reqGroupFilter,
        crop_id: override?.crop_id ?? reqCropFilter,
        sido: override?.sido ?? reqSidoFilter,
        sigungu: override?.sigungu ?? reqSigunguFilter,
        eupmyeondong: override?.eupmyeondong ?? reqDongFilter,
        cultivation_type: override?.cultivation_type ?? reqTypeFilter,
        request_status: override?.request_status ?? reqStatusFilter,
        q: (override?.q ?? reqKeyword).trim(),
      });
      let fetchRes = await fetch(`/api/member-schedule-requests?${params.toString()}`).catch(() => null);
      if (!fetchRes || !fetchRes.ok) {
        await new Promise((resolve) => setTimeout(resolve, 250));
        fetchRes = await fetch(`/api/member-schedule-requests?${params.toString()}`).catch(() => null);
      }
      if (fetchRes && fetchRes.ok) {
        const res = await fetchRes.json();
        if (Array.isArray(res?.items)) {
          setReqResult({
            items: res.items,
            total: res.total ?? res.items.length,
            summary: res.summary || null,
          });
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsReqLoading(false);
    }
  };

  const handleSaveScheduleReq = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!reqForm.request_no || !reqForm.item_name_3rd) return;
    if (
      reqFormMode === 'edit' &&
      !window.confirm(
        `[${reqForm.request_no} - ${reqForm.item_name_3rd}] 재배 일정 수정 내용을 저장하시겠습니까?`
      )
    ) {
      return;
    }
    await fetch('/api/member-schedule-requests/save', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...reqForm, member_id: 'CloudBae@naver.com (배철민)' }),
    });
    showToast(`재배 일정 [${reqForm.request_no} · ${reqForm.item_name_3rd}] 저장 완료 (Supabase 실시간 동기화)`);
    setIsReqFormModalOpen(false);
    executeScheduleReqSearch();
    loadScheduleProvisionData(reqForm.request_no);
  };

  const handleDeleteScheduleReq = async (requestNo: string, itemName: string) => {
    if (!window.confirm(`재배 일정 [${requestNo} - ${itemName}] 항목을 정말 삭제하시겠습니까?`)) return;
    await fetch('/api/member-schedule-requests/delete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ request_no: requestNo }),
    });
    showToast(`재배 일정 [${requestNo}] 삭제 완료 (Supabase 실시간 반영)`);
    if (selectedReqDetail?.request_no === requestNo) {
      setSelectedReqDetail(null);
    }
    if (provisionRequestNo === requestNo) {
      setIsProvisionScheduleModalOpen(false);
      setClickedProvisionItem(null);
      setHoveredProvisionItem(null);
    }
    executeScheduleReqSearch();
    loadScheduleProvisionData();
  };

  useEffect(() => {
    loadReqDongs(reqSidoFilter, reqSigunguFilter);
  }, [reqSidoFilter, reqSigunguFilter]);

  const scheduleReqDataVersion = '2026-11-06-normalized-v2';
  useEffect(() => {
    if (activeTab === 'schedule_requests') {
      executeScheduleReqSearch();
    }
  }, [activeTab, overview, scheduleReqDataVersion]);

