  const buildDefaultBankForm = (itemsList: any[] = bankAccountsData.items) => {
    const existingNums = itemsList.map((item: any) => {
      const m = String(item.account_id || '').match(/(\d+)$/);
      return m ? Number(m[1]) : 0;
    });
    const nextNum = Math.max(5, ...existingNums) + 1;
    const nextId = `BANK-ACC-${String(nextNum).padStart(2, '0')}`;
    return {
      account_id: nextId,
      bank_code: '011',
      bank_name: 'NH농협은행',
      account_number: '',
      account_holder: '(주)팜플랜농자재',
      account_purpose: '비료·영양재·병해충관리제 통합 구입 결제',
      branch_name: '',
      is_primary: 0,
      is_active: 1,
      auto_confirm_enabled: 1,
      cash_receipt_info: '현금영수증(소득공제/지출증빙) 및 전자세금계산서 100% 발행 가능',
      transfer_guide_memo: '입금자명을 주문자 성함(또는 농장명)과 동일하게 입력해 주시면 자동 입금확인 처리됩니다.',
      sort_order: nextNum,
    };
  };

  const resetBankFormToCreate = (itemsList: any[] = bankAccountsData.items) => {
    setBankForm(buildDefaultBankForm(itemsList));
    setBankModalMode('create');
  };

  const loadPaymentBankAccounts = async (override?: {
    bank_code?: string;
    is_active?: string;
    q?: string;
  }) => {
    setIsBankLoading(true);
    try {
      const params = new URLSearchParams({
        bank_code: override?.bank_code ?? bankCodeFilter,
        is_active: override?.is_active ?? bankActiveFilter,
        q: (override?.q ?? bankSearchKeyword).trim(),
      });
      const res = await fetch(`/api/payment-bank-accounts?${params.toString()}`).then((r) => r.json());
      const loadedItems = res.items || [];
      setBankAccountsData({
        items: loadedItems,
        totalCount: res.totalCount || 0,
        activeCount: res.activeCount || 0,
        primaryAccount: res.primaryAccount || null,
      });
      return loadedItems;
    } catch (e) {
      console.error(e);
      return [];
    } finally {
      setIsBankLoading(false);
    }
  };

  const openNewBankAccountModal = () => {
    setBankForm(buildDefaultBankForm(bankAccountsData.items));
    setBankModalMode('create');
    setIsBankModalOpen(true);
  };

  const handleSaveBankAccount = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!bankForm.account_id || !bankForm.account_number || !bankForm.account_holder) {
      window.alert('계좌 관리코드, 계좌번호, 예금주명을 모두 입력해 주세요.');
      return;
    }
    const res = await fetch('/api/payment-bank-accounts', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...bankForm, mode: bankModalMode }),
    });
    const data = await res.json().catch(() => ({ ok: res.ok }));
    if (!res.ok || data.ok === false) {
      window.alert(data.message || '결제용 은행계좌 저장 중 오류가 발생했습니다.');
      return;
    }
    showToast(
      `결제용 은행계좌 [${bankForm.bank_name} ${bankForm.account_number}] ${
        bankModalMode === 'create' ? '신규 등록' : '수정'
      } 완료`
    );
    setIsBankModalOpen(false);
    const updatedItems = await loadPaymentBankAccounts();
    resetBankFormToCreate(updatedItems);
  };

  const handleSetPrimaryBankAccount = async (acc: any) => {
    await fetch('/api/payment-bank-accounts/set-primary', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ account_id: acc.account_id }),
    });
    showToast(`[${acc.bank_name} ${acc.account_number}] 계좌가 제품 구입 대표 입금계좌로 지정되었습니다.`);
    loadPaymentBankAccounts();
  };

  const handleToggleBankAccountActive = async (acc: any) => {
    const nextState = Number(acc.is_active) === 1 ? 0 : 1;
    await fetch('/api/payment-bank-accounts/toggle-active', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ account_id: acc.account_id, is_active: nextState }),
    });
    showToast(
      `[${acc.bank_name} ${acc.account_number}] 계좌가 ${nextState === 1 ? '사용중(주문서 노출)' : '사용중지(숨김)'} 상태로 변경되었습니다.`
    );
    loadPaymentBankAccounts();
  };

  const handleDeleteBankAccount = async (acc: any) => {
    if (
      !window.confirm(
        `결제용 은행계좌 [${acc.bank_name} ${acc.account_number} (${acc.account_holder})] 항목을 삭제하시겠습니까?`
      )
    ) {
      return;
    }
    await fetch('/api/payment-bank-accounts/delete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ account_id: acc.account_id }),
    });
    showToast(`결제용 은행계좌 [${acc.bank_name} ${acc.account_number}] 삭제 완료`);
    loadPaymentBankAccounts();
  };

  // 4-1. 작물별 생육 과정 관리 (1·2단계 · 제품(품종)별 생육과정 + 생육기간 + 작업내용(nvarchar(1000)) + 필요 농자재 + 사용팁(nvarchar(1000)))
  const [cgpPlansData, setCgpPlansData] = useState<{
    items: any[];
    totalCount: number;
    allMaterials: any[];
  }>({
    items: [],
    totalCount: 0,
    allMaterials: [],
  });
  const [isCgpLoading, setIsCgpLoading] = useState(false);
  const [cgpGroupFilter, setCgpGroupFilter] = useState('ALL');
  const [cgpCropFilter, setCgpCropFilter] = useState('ALL');
  const [cgpCultivarFilter, setCgpCultivarFilter] = useState('ALL');
  const [cgpSearchKeyword, setCgpSearchKeyword] = useState('');
  const [isCgpModalOpen, setIsCgpModalOpen] = useState(false);
  const [selectedCgpDetail, setSelectedCgpDetail] = useState<any | null>(null);
  const [cgpFormMode, setCgpFormMode] = useState<'create' | 'edit'>('create');
  const [cgpMatCategoryFilter, setCgpMatCategoryFilter] = useState('ALL');
  const [cgpSelectedMaterialToAdd, setCgpSelectedMaterialToAdd] = useState('FERT-PRD-01');
  const [cgpForm, setCgpForm] = useState<any>({
    plan_id: 'CGP-CAB-BRM3-05',
    group_id: 'GRP-LEAF',
    group_name: '엽채류 (잎채소)',
    crop_id: 'CRP-CABBAGE',
    crop_name: '가을배추',
    cultivar_id: 'CV-BRM3',
    cultivar_name: '불암3호',
    template_id: 'TPL-GRP-LEAF-CRP-CABBAGE-CV-BRM3-07',
    process_code: 'PRC-20',
    process_name: '2차 웃거름',
    process_type: 'STG-GROWTH',
    step_order: 5,
    target_pgdd: 590,
    start_date: '',
    end_date: '',
    work_content: '',
    required_materials: [],
    usage_tip: '',
  });

  const generateNextCgpPlanId = (
    cropId: string,
    cultivarId: string,
    existingItems: any[] = cgpPlansData.items
  ) => {
    const cleanCrop = (cropId || 'CRP').replace(/^CRP-/, '').slice(0, 4).toUpperCase();
    const cleanCv = (cultivarId || 'CV').replace(/^CV-/, '').slice(0, 6).toUpperCase();
    const prefix = `CGP-${cleanCrop}-${cleanCv}-`;
    let seq =
      existingItems.filter(
        (it: any) => it.crop_id === cropId && it.cultivar_id === cultivarId
      ).length + 1;
    let candidate = `${prefix}${String(seq).padStart(2, '0')}`;
    while (
      existingItems.some(
        (it: any) => String(it.plan_id || '').toUpperCase() === candidate.toUpperCase()
      )
    ) {
      seq++;
      candidate = `${prefix}${String(seq).padStart(2, '0')}`;
    }
    return candidate;
  };

  const loadCropGrowthProcessPlans = async (override?: {
    group_id?: string;
    crop_id?: string;
    cultivar_id?: string;
    q?: string;
  }) => {
    setIsCgpLoading(true);
    try {
      const params = new URLSearchParams({
        group_id: override?.group_id ?? cgpGroupFilter,
        crop_id: override?.crop_id ?? cgpCropFilter,
        cultivar_id: override?.cultivar_id ?? cgpCultivarFilter,
        q: (override?.q ?? cgpSearchKeyword).trim(),
      });
      const res = await fetch(`/api/crop-growth-process-plans?${params.toString()}`).then((r) => r.json());
      const items = res.items || [];
      const allMaterials = res.allMaterials || [];
      setCgpPlansData({
        items,
        totalCount: res.totalCount || 0,
        allMaterials,
      });
      if (allMaterials.length > 0 && !cgpSelectedMaterialToAdd) {
        setCgpSelectedMaterialToAdd(allMaterials[0].material_id);
      }
      return { items, allMaterials };
    } catch (e) {
      console.error(e);
      return { items: [], allMaterials: [] };
    } finally {
      setIsCgpLoading(false);
    }
  };

  const resetCgpFormToCreate = (
    groupId = cgpForm.group_id || 'GRP-LEAF',
    cropId = cgpForm.crop_id || 'CRP-CABBAGE',
    cultivarId = cgpForm.cultivar_id || 'CV-BRM3',
    existingItems = cgpPlansData.items
  ) => {
    const groupObj = overview?.groups?.find((g: any) => g.group_id === groupId);
    const cropObj = overview?.crops?.find((c: any) => c.crop_id === cropId);
    const cultivarObj = overview?.cultivars?.find((cv: any) => cv.cultivar_id === cultivarId);
    const matchingTpls = templates.filter((t: any) => {
      const sysObj = overview?.systems?.find((s: any) => s.system_id === t.system_id);
      const tCrop = t.crop_id || sysObj?.crop_id;
      const tCv = t.cultivar_id || '';
      if (tCrop !== cropId) return false;
      if (tCv && cultivarId && tCv !== cultivarId) return false;
      return true;
    });
    const usedProcessCodes = new Set(
      existingItems
        .filter((it: any) => it.crop_id === cropId && it.cultivar_id === cultivarId)
        .map((it: any) => it.process_code)
    );
    const nextTpl =
      matchingTpls.find((t: any) => !usedProcessCodes.has(t.item_code)) ||
      matchingTpls[0] ||
      null;
    const firstBasic = (overview?.growthProcessCodes || [])[0];
    const nextStepOrder =
      existingItems.filter((it: any) => it.crop_id === cropId && it.cultivar_id === cultivarId).length + 1;
    const nextId = generateNextCgpPlanId(cropId, cultivarId, existingItems);
    const rawProcessName = nextTpl?.item_name || firstBasic?.process_name || '';

    setCgpForm({
      plan_id: nextId,
      group_id: groupId,
      group_name: groupObj?.group_name || '엽채류 (잎채소)',
      crop_id: cropId,
      crop_name: cropObj?.crop_name || '가을배추',
      cultivar_id: cultivarId,
      cultivar_name: cultivarObj?.cultivar_name || '불암3호',
      template_id: nextTpl?.template_id || '',
      process_code: nextTpl?.item_code || firstBasic?.process_code || 'PRC-01',
      process_name: String(rawProcessName).split('(')[0].trim(),
      process_type: nextTpl?.item_type || firstBasic?.process_type || 'STG-PREP',
      step_order: nextStepOrder,
      target_pgdd: nextTpl?.target_pgdd ?? 0,
      start_date: '',
      end_date: '',
      work_content: nextTpl?.guide_criteria || '',
      required_materials: [],
      usage_tip: '',
    });
    setCgpFormMode('create');
  };

  const handleAddMaterialToCgpForm = (matId?: string) => {
    const targetId = matId || cgpSelectedMaterialToAdd;
    if (!targetId) return;
    const found = cgpPlansData.allMaterials.find((m: any) => m.material_id === targetId);
    if (!found) return;
    const currentList = Array.isArray(cgpForm.required_materials) ? cgpForm.required_materials : [];
    if (currentList.some((m: any) => m.material_id === found.material_id)) {
      showToast(`이미 추가된 농자재입니다: [${found.product_name}]`);
      return;
    }
    const newEntry = {
      material_id: found.material_id,
      material_category: found.material_category,
      sub_type: found.sub_type,
      product_name: found.product_name,
      manufacturer: found.manufacturer || '한팜',
      weight_spec: found.weight_spec || found.unit_spec || '',
      nutrient_ratio_summary: found.nutrient_ratio_summary || found.target_nutrient_or_pest || '',
      dosage_per_100pyeong: found.dosage_per_100pyeong || '',
      unit_price: found.unit_price || 0,
      thumbnail_url:
        found.thumbnail_url || `/api/agro-materials/image/${encodeURIComponent(found.material_id)}/thumb`,
    };
    const nextMaterials = [...currentList, newEntry];
    setCgpForm({
      ...cgpForm,
      required_materials: nextMaterials,
    });
    showToast(`필요 농자재 [${found.product_name}] 추가 완료`);
  };

  const handleRemoveMaterialFromCgpForm = (materialId: string) => {
    const currentList = Array.isArray(cgpForm.required_materials) ? cgpForm.required_materials : [];
    setCgpForm({
      ...cgpForm,
      required_materials: currentList.filter((m: any) => m.material_id !== materialId),
    });
  };

  const handleAutoFillUsageTipFromMaterials = () => {
    const currentList = Array.isArray(cgpForm.required_materials) ? cgpForm.required_materials : [];
    if (currentList.length === 0) {
      window.alert('먼저 필요한 농자재를 1개 이상 선택해 추가해 주세요.');
      return;
    }
    const lines = currentList.map(
      (m: any, idx: number) =>
        `${idx + 1}. [${m.manufacturer || '한팜'}] ${m.product_name} (${m.sub_type}): 100평당 ${
          m.dosage_per_100pyeong || '표준 정량'
        } 시비·살포 (${m.nutrient_ratio_summary || ''})`
    );
    const autoText = `[농자재 사용팁 (${cgpForm.process_name})]\n${lines.join('\n')}\n• 시비·살포 시 강우 직전이나 한낮 고온기를 피하고 정량을 준수해 주세요.`.slice(
      0,
      1000
    );
    setCgpForm({
      ...cgpForm,
      usage_tip: autoText,
    });
    showToast('선택된 농자재 기준 사용팁이 자동 작성되었습니다.');
  };

  const handleSaveCropGrowthProcessPlan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!cgpForm.group_id || !cgpForm.crop_id || !cgpForm.cultivar_id || !cgpForm.process_name) {
      window.alert('1단계 적용군, 2단계 적용 작물분류, 3단계 제품명 및 생육과정명을 선택해 주세요.');
      return;
    }
    const res = await fetch('/api/crop-growth-process-plans', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...cgpForm,
        start_date: '',
        end_date: '',
        work_content: String(cgpForm.work_content || '').slice(0, 1000),
        usage_tip: String(cgpForm.usage_tip || '').slice(0, 1000),
        mode: cgpFormMode,
      }),
    });
    const data = await res.json().catch(() => ({ ok: res.ok }));
    if (!res.ok || data.ok === false) {
      window.alert(data.message || '작물별 생육 과정 저장 중 오류가 발생했습니다.');
      return;
    }
    showToast(
      `[${cgpForm.crop_name} · ${cgpForm.cultivar_name}] #${cgpForm.step_order} ${cgpForm.process_name} ${
        cgpFormMode === 'create' ? '신규 등록' : '수정'
      } 완료`
    );
    setIsCgpModalOpen(false);
    const { items } = await loadCropGrowthProcessPlans();
    resetCgpFormToCreate(cgpForm.group_id, cgpForm.crop_id, cgpForm.cultivar_id, items);
  };

  const handleDeleteCropGrowthProcessPlan = async (item: any) => {
    if (
      !window.confirm(
        `[${item.crop_name} · ${item.cultivar_name}] "${item.process_name}" 생육 과정을 삭제하시겠습니까?`
      )
    ) {
      return;
    }
    await fetch('/api/crop-growth-process-plans/delete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ plan_id: item.plan_id }),
    });
    showToast(`생육 과정 [${item.process_name}] 삭제 완료`);
    loadCropGrowthProcessPlans();
  };

  // ==================== 설문조사 관리 (한팜 맞춤형 재배관리 서비스 수요조사 URL 배포 · 응답 수집 · 통계 관리) ====================
