  // TPL-"농작물1차분류코드"-"농작물2차분류코드"-"농작물명코드" 자동 생성 및 중복 방지 헬퍼
  const generateUniqueTemplateId = (
    groupId: string,
    cropId: string,
    cultivarId: string,
    excludeTemplateId?: string
  ) => {
    const gCode = (groupId || 'GRP').trim();
    const cCode = (cropId || 'CRP').trim();
    const cvCode = (cultivarId || cCode || 'COMMON').trim();
    const baseId = `TPL-${gCode}-${cCode}-${cvCode}`;

    const existingUpperIds = new Set(
      templates
        .filter((t) => !excludeTemplateId || t.template_id !== excludeTemplateId)
        .map((t) => String(t.template_id || '').toUpperCase())
    );

    if (!existingUpperIds.has(baseId.toUpperCase())) {
      return baseId;
    }

    let seq = 2;
    while (existingUpperIds.has(`${baseId}-${String(seq).padStart(2, '0')}`.toUpperCase())) {
      seq++;
    }
    return `${baseId}-${String(seq).padStart(2, '0')}`;
  };

  // 3. 생육과정 관리 (standard_template) 등록/수정 및 삭제 핸들러
  const handleSaveTemplate = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmedId = (templateForm.template_id || '').trim();
    if (!trimmedId || !templateForm.item_name) return;

    if (templateModalMode === 'create') {
      const isDuplicate = templates.some(
        (t) => String(t.template_id || '').toUpperCase() === trimmedId.toUpperCase()
      );
      if (isDuplicate) {
        window.alert(`이미 등록된 생육과정 템플릿 ID(${trimmedId})입니다.\n중복될 수 없으므로 다른 코드 또는 자동생성 코드를 사용해 주세요.`);
        return;
      }
    }

    const res = await fetch('/api/templates', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...templateForm, template_id: trimmedId, mode: templateModalMode }),
    });
    const data = await res.json().catch(() => ({ ok: res.ok }));
    if (!res.ok || data.ok === false) {
      window.alert(data.message || '생육과정 템플릿 저장 중 중복 또는 오류가 발생했습니다.');
      return;
    }
    showToast(`생육과정 [${templateForm.item_name} (${trimmedId})] 저장 완료`);
    setIsTemplateModalOpen(false);
    loadAllData();
  };

